//! Integration tests for RRD S3 streaming with real RRD files.
//!
//! These tests use actual RRD files generated by the RrdWriter to verify
//! that the S3 streaming parser works correctly with real-world data.

use std::fs;
use std::path::Path;

use robocodec::io::formats::rrd::stream::{
    MessageKind, RRD_STREAM_MAGIC, RrdMessageRecord, StreamingRrdParser,
};
use robocodec::io::s3::StreamingParser;

/// Helper function to load a test fixture file.
fn load_fixture(name: &str) -> Vec<u8> {
    let path = Path::new("tests/fixtures/rrd").join(name);
    fs::read(&path).unwrap_or_else(|_| panic!("Failed to read fixture: {}", name))
}

#[test]
fn test_real_rrd_small_uncompressed() {
    let data = load_fixture("small_uncompressed.rrd");

    // Verify magic
    assert_eq!(&data[0..4], RRD_STREAM_MAGIC);

    println!("File size: {}", data.len());

    let mut parser = StreamingRrdParser::new();
    let messages = parser.parse_chunk(&data).expect("Failed to parse RRD");

    println!("Parsed {} messages", messages.len());
    println!("Message count: {}", parser.message_count());
    println!("Initialized: {}", parser.is_initialized());
    println!("Has channels: {}", parser.has_channels());
    println!("Channel count: {}", parser.channels().len());

    // Should have parsed all 10 messages
    assert_eq!(messages.len(), 10);
    assert_eq!(parser.message_count(), 10);
    assert!(parser.is_initialized());
    assert!(parser.has_channels());
}

