#[test]
fn test_real_rrd_large_multichannel() {
    let data = load_fixture("large_multichannel.rrd");

    // Verify magic
    assert_eq!(&data[0..4], RRD_STREAM_MAGIC);

    let mut parser = StreamingRrdParser::new();
    let messages = parser.parse_chunk(&data).expect("Failed to parse RRD");

    // Should have parsed all 200 messages
    // Note: RRF2 format doesn't have explicit channel IDs - entity paths are in Protobuf payload
    // Our simple fixtures use plain text, so all messages use the default topic
    assert_eq!(messages.len(), 200);
    assert_eq!(parser.message_count(), 200);
    assert_eq!(parser.channels().len(), 1); // Default topic for ArrowMsg
}

#[test]
fn test_real_rrd_timestamps() {
    let data = load_fixture("timestamps.rrd");

    // Verify magic
    assert_eq!(&data[0..4], RRD_STREAM_MAGIC);

    let mut parser = StreamingRrdParser::new();
    let messages = parser.parse_chunk(&data).expect("Failed to parse RRD");

    // Should have parsed all 25 messages
    assert_eq!(messages.len(), 25);
    assert_eq!(parser.message_count(), 25);

    // Verify message kind and topic
    for msg in &messages {
        assert_eq!(msg.kind, MessageKind::ArrowMsg);
        assert!(!msg.topic.is_empty());
    }
}

#[test]
fn test_real_rrd_chunked_parsing() {
    let data = load_fixture("large_multichannel.rrd");

    let mut parser = StreamingRrdParser::new();

    // Simulate streaming by parsing in chunks
    let chunk_size = 1024;
    let mut total_messages = 0;
    let mut offset = 0;

    while offset < data.len() {
        let end = (offset + chunk_size).min(data.len());
        let chunk = &data[offset..end];

        match parser.parse_chunk(chunk) {
            Ok(messages) => {
                let messages: Vec<RrdMessageRecord> = messages;
                total_messages += messages.len() as u64;
            }
            Err(e) => {
                // Expected when we need more data
                let error_msg = format!("{:?}", e);
                if !error_msg.contains("Need") && !error_msg.contains("require more") {
                    panic!("Unexpected error: {}", e);
                }
            }
        }

        offset = end;

        // Break if we've processed everything
        if total_messages >= 200 {
            break;
        }
    }

    // Verify we got all messages
    assert_eq!(parser.message_count(), 200);
}

#[test]
fn test_real_rrd_channel_info() {
    let data = load_fixture("large_multichannel.rrd");

    let mut parser = StreamingRrdParser::new();
    parser.parse_chunk(&data).expect("Failed to parse RRD");

    let channels = parser.channels();
    // RRF2 format uses entity paths from Protobuf payload, not numeric channel IDs
    // Our simple fixtures use plain text, so we get the default topic
    assert_eq!(channels.len(), 1);

    // Verify default topic exists
    assert!(channels.contains_key(&0));
    assert_eq!(channels[&0].topic, "/");
}

#[test]
fn test_real_rrd_message_content() {
    let data = load_fixture("small_uncompressed.rrd");

    let mut parser = StreamingRrdParser::new();
    let messages = parser.parse_chunk(&data).expect("Failed to parse RRD");

    // Check first message contains expected text
    let first_msg = &messages[0];
    assert!(first_msg.data.starts_with(b"message 0"));

    // Check last message
    let last_msg = &messages[messages.len() - 1];
    assert!(last_msg.data.starts_with(b"message 9"));
}

#[test]
fn test_all_rrd_fixtures_have_valid_magic() {
    let fixtures = vec![
        "small_uncompressed.rrd",
        "medium_lz4.rrd",
        "large_multichannel.rrd",
        "timestamps.rrd",
    ];

    for fixture in fixtures {
        let data = load_fixture(fixture);
        assert_eq!(
            &data[0..4],
            RRD_STREAM_MAGIC,
            "Fixture {} has invalid magic",
            fixture
        );
    }
}

